            res.append({"Name": base, "Value": e["Value"], "Version": e["Version"], "Type": e["Type"], "LastModifiedDate": e["LastModifiedDate"], "ARN": "arn:aws:ssm:us-east-1:123456789012:parameter"+base, "DataType": "text", "Selector": (":"+sel) if sel else None})
