package awsclient

import (
	"errors"
	"fmt"
)

// APIError is an error returned by an AWS service.
type APIError struct {
	Code    string
	Message string
	// Modeled indicates whether the error type is part of the operation's
	// model (which changes how it is rendered).
	Modeled bool
	Fault   string
}

func (e *APIError) Error() string {
	if e.Modeled {
		return fmt.Sprintf("%s: %s", e.Code, e.Message)
	}
	return fmt.Sprintf("api error %s: %s", e.Code, e.Message)
}

func (e *APIError) ErrorCode() string { return e.Code }

// ResponseError wraps an error with HTTP response metadata.
type ResponseError struct {
	StatusCode int
	RequestID  string
	HostID     string
	Err        error
}

func (e *ResponseError) Error() string {
	if e.HostID != "" {
		return fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, HostID: %s, %v", e.StatusCode, e.RequestID, e.HostID, e.Err)
	}
	return fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, %v", e.StatusCode, e.RequestID, e.Err)
}

func (e *ResponseError) Unwrap() error { return e.Err }

// OperationError wraps an error with the service and operation names.
type OperationError struct {
	Service   string
	Operation string
	Err       error
}

func (e *OperationError) Error() string {
	return fmt.Sprintf("operation error %s: %s, %v", e.Service, e.Operation, e.Err)
}

func (e *OperationError) Unwrap() error { return e.Err }

// MaxAttemptsError is returned when all retry attempts are exhausted.
type MaxAttemptsError struct {
	Attempts int
	Err      error
}

func (e *MaxAttemptsError) Error() string {
	return fmt.Sprintf("exceeded maximum number of attempts, %d, %v", e.Attempts, e.Err)
}

func (e *MaxAttemptsError) Unwrap() error { return e.Err }

// RequestSendError is returned when the HTTP request could not be sent.
type RequestSendError struct {
	Err error
}

func (e *RequestSendError) Error() string {
	return fmt.Sprintf("request send failed, %v", e.Err)
}

func (e *RequestSendError) Unwrap() error { return e.Err }

// DeserializationError is returned when a response could not be decoded.
type DeserializationError struct {
	Err error
}

func (e *DeserializationError) Error() string {
	return fmt.Sprintf("deserialization failed, %v", e.Err)
}

func (e *DeserializationError) Unwrap() error { return e.Err }

// ErrorCode extracts the AWS error code from an error chain, if any.
func ErrorCode(err error) string {
	var ae *APIError
	if errors.As(err, &ae) {
		return ae.Code
	}
	return ""
}

// IsErrorCode reports whether err carries the given AWS error code.
func IsErrorCode(err error, codes ...string) bool {
	c := ErrorCode(err)
	if c == "" {
		return false
	}
	for _, code := range codes {
		if c == code {
			return true
		}
	}
	return false
}

// HTTPStatusCode extracts the HTTP status code of a response error.
func HTTPStatusCode(err error) int {
	var re *ResponseError
	if errors.As(err, &re) {
		return re.StatusCode
	}
	return 0
}
