package awsclient

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

// Credentials holds a set of AWS credentials.
type Credentials struct {
	AccessKeyID     string
	SecretAccessKey string
	SessionToken    string
	Source          string
}

// Config is the resolved AWS configuration used by the clients.
type Config struct {
	Region      string
	MaxAttempts int
	RetryMode   string
	HTTPClient  *http.Client

	// EndpointURL is the global endpoint override (AWS_ENDPOINT_URL).
	EndpointURL string
	// ServiceEndpoints holds per-service endpoint overrides keyed by the
	// service identifier (e.g. "ssm").
	ServiceEndpoints map[string]string

	credsMu      sync.Mutex
	creds        *Credentials
	credsErr     error
	credsLoaded  bool
	profile      string
	sharedConfig map[string]string
	imdsDisabled bool
}

// Options control how the configuration is loaded.
type Options struct {
	Region      string
	MaxAttempts int
	RetryMode   string
}

func envOr(keys ...string) string {
	for _, k := range keys {
		if v := os.Getenv(k); v != "" {
			return v
		}
	}
	return ""
}

func userHomeDir() string {
	if h := os.Getenv("HOME"); h != "" {
		return h
	}
	h, _ := os.UserHomeDir()
	return h
}

// parseSharedFile parses an AWS shared config/credentials file into a map of
// section name -> key -> value.
func parseSharedFile(path string) (map[string]map[string]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	result := map[string]map[string]string{}
	var cur map[string]string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") || strings.HasPrefix(trimmed, ";") {
			continue
		}
		if strings.HasPrefix(trimmed, "[") && strings.HasSuffix(trimmed, "]") {
			name := strings.TrimSpace(trimmed[1 : len(trimmed)-1])
			cur = result[name]
			if cur == nil {
				cur = map[string]string{}
				result[name] = cur
			}
			continue
		}
		if cur == nil {
			continue
		}
		if strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t") {
			// nested property (e.g. s3 settings); ignore
			continue
		}
		idx := strings.Index(trimmed, "=")
		if idx < 0 {
			continue
		}
		key := strings.ToLower(strings.TrimSpace(trimmed[:idx]))
		val := strings.TrimSpace(trimmed[idx+1:])
		cur[key] = val
	}
	return result, scanner.Err()
}

func sharedCredentialsPath() string {
	if p := os.Getenv("AWS_SHARED_CREDENTIALS_FILE"); p != "" {
		return p
	}
	return filepath.Join(userHomeDir(), ".aws", "credentials")
}

func sharedConfigPath() string {
	if p := os.Getenv("AWS_CONFIG_FILE"); p != "" {
		return p
	}
	return filepath.Join(userHomeDir(), ".aws", "config")
}

// loadSharedProfile merges the settings of the named profile from the
// shared config and credentials files.
func loadSharedProfile(profile string, explicit bool) (map[string]string, bool, error) {
	merged := map[string]string{}
	found := false
	if cfg, err := parseSharedFile(sharedConfigPath()); err == nil {
		section := profile
		if profile != "default" {
			section = "profile " + profile
		}
		if sec, ok := cfg[section]; ok {
			found = true
			for k, v := range sec {
				merged[k] = v
			}
		} else if sec, ok := cfg[profile]; ok && profile == "default" {
			found = true
			for k, v := range sec {
				merged[k] = v
			}
		}
	}
	if creds, err := parseSharedFile(sharedCredentialsPath()); err == nil {
		if sec, ok := creds[profile]; ok {
			found = true
			for k, v := range sec {
				merged[k] = v
			}
		}
	}
	if !found && explicit {
		return nil, false, fmt.Errorf("failed to get shared config profile, %s", profile)
	}
	return merged, found, nil
}

// LoadConfig resolves the AWS configuration from the environment and the
// shared configuration files.
func LoadConfig(ctx context.Context, opts Options) (*Config, error) {
	cfg := &Config{
		MaxAttempts:      opts.MaxAttempts,
		RetryMode:        opts.RetryMode,
		ServiceEndpoints: map[string]string{},
	}
	cfg.HTTPClient = &http.Client{
		Transport: &http.Transport{
			Proxy: http.ProxyFromEnvironment,
			DialContext: (&net.Dialer{
				Timeout:   30 * time.Second,
				KeepAlive: 30 * time.Second,
			}).DialContext,
			ForceAttemptHTTP2:     true,
			MaxIdleConns:          100,
			IdleConnTimeout:       90 * time.Second,
			TLSHandshakeTimeout:   10 * time.Second,
			ExpectContinueTimeout: 1 * time.Second,
		},
	}

	profile := os.Getenv("AWS_PROFILE")
	explicit := profile != ""
	if profile == "" {
		profile = "default"
	}
	cfg.profile = profile
	shared, _, err := loadSharedProfile(profile, explicit)
	if err != nil {
		return nil, err
	}
	cfg.sharedConfig = shared

	// region resolution
	region := opts.Region
	if region == "" {
		region = envOr("AWS_REGION", "AWS_DEFAULT_REGION")
	}
	if region == "" {
		region = shared["region"]
	}
	cfg.Region = region

	// endpoint resolution
	if v := os.Getenv("AWS_ENDPOINT_URL"); v != "" {
		cfg.EndpointURL = v
	} else if v := shared["endpoint_url"]; v != "" {
		cfg.EndpointURL = v
	}
	for _, env := range os.Environ() {
		if strings.HasPrefix(env, "AWS_ENDPOINT_URL_") {
			kv := strings.SplitN(env, "=", 2)
			if len(kv) != 2 || kv[1] == "" {
				continue
			}
			svc := strings.ToLower(strings.TrimPrefix(kv[0], "AWS_ENDPOINT_URL_"))
			cfg.ServiceEndpoints[svc] = kv[1]
		}
	}

	if v := strings.ToLower(os.Getenv("AWS_EC2_METADATA_DISABLED")); v == "true" {
		cfg.imdsDisabled = true
	}

	return cfg, nil
}

// EndpointFor returns the endpoint URL for the given service identifier.
func (c *Config) EndpointFor(serviceID string, defaultHost string) (string, bool) {
	key := strings.ToLower(strings.ReplaceAll(serviceID, " ", "_"))
	if v, ok := c.ServiceEndpoints[key]; ok {
		return v, true
	}
	if c.EndpointURL != "" {
		return c.EndpointURL, true
	}
	return defaultHost, false
}

// Credentials resolves (and caches) the credentials using the default
// credential provider chain.
func (c *Config) Credentials(ctx context.Context) (*Credentials, error) {
	c.credsMu.Lock()
	defer c.credsMu.Unlock()
	if c.credsLoaded {
		return c.creds, c.credsErr
	}
	c.credsLoaded = true
	creds, err := c.resolveCredentials(ctx)
	c.creds, c.credsErr = creds, err
	return creds, err
}

func (c *Config) resolveCredentials(ctx context.Context) (*Credentials, error) {
	// 1. environment variables
	if ak := envOr("AWS_ACCESS_KEY_ID", "AWS_ACCESS_KEY"); ak != "" {
		sk := envOr("AWS_SECRET_ACCESS_KEY", "AWS_SECRET_KEY")
		if sk != "" {
			return &Credentials{
				AccessKeyID:     ak,
				SecretAccessKey: sk,
				SessionToken:    os.Getenv("AWS_SESSION_TOKEN"),
				Source:          "EnvConfigCredentials",
			}, nil
		}
	}
	// 2. shared config/credentials files
	if ak := c.sharedConfig["aws_access_key_id"]; ak != "" {
		if sk := c.sharedConfig["aws_secret_access_key"]; sk != "" {
			return &Credentials{
				AccessKeyID:     ak,
				SecretAccessKey: sk,
				SessionToken:    c.sharedConfig["aws_session_token"],
				Source:          "SharedConfigCredentials",
			}, nil
		}
	}
	// 3. container credentials
	if rel := os.Getenv("AWS_CONTAINER_CREDENTIALS_RELATIVE_URI"); rel != "" {
		return fetchContainerCredentials(ctx, c.HTTPClient, "http://169.254.170.2"+rel, os.Getenv("AWS_CONTAINER_AUTHORIZATION_TOKEN"))
	}
	if full := os.Getenv("AWS_CONTAINER_CREDENTIALS_FULL_URI"); full != "" {
		return fetchContainerCredentials(ctx, c.HTTPClient, full, os.Getenv("AWS_CONTAINER_AUTHORIZATION_TOKEN"))
	}
	// 4. EC2 instance metadata
	return c.imdsCredentials(ctx)
}

type credsResponse struct {
	AccessKeyId     string
	SecretAccessKey string
	Token           string
	Expiration      string
	Code            string
}

func fetchContainerCredentials(ctx context.Context, client *http.Client, url, token string) (*Credentials, error) {
	req, err := http.NewRequestWithContext(ctx, "GET", url, nil)
	if err != nil {
		return nil, fmt.Errorf("get identity: get credentials: failed to refresh cached credentials, %v", err)
	}
	if token != "" {
		req.Header.Set("Authorization", token)
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("get identity: get credentials: failed to refresh cached credentials, failed to load credentials, %v", err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	var cr credsResponse
	if err := decodeJSON(body, &cr); err != nil || cr.AccessKeyId == "" {
		return nil, fmt.Errorf("get identity: get credentials: failed to refresh cached credentials, failed to load credentials, response status code %d", resp.StatusCode)
	}
	return &Credentials{AccessKeyID: cr.AccessKeyId, SecretAccessKey: cr.SecretAccessKey, SessionToken: cr.Token, Source: "ContainerCredentials"}, nil
}

const imdsBase = "http://169.254.169.254"

// imdsCredentials attempts to retrieve credentials from the EC2 instance
// metadata service, mimicking the error reporting of the AWS SDK.
func (c *Config) imdsCredentials(ctx context.Context) (*Credentials, error) {
	const prefix = "get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, "
