			if resp.StatusCode == 404 {
				return nil, &credentialsError{msg: prefix + fmt.Sprintf("http response error StatusCode: %d, request to EC2 IMDS failed", resp.StatusCode)}
			}
			lastErr = fmt.Errorf("http response error StatusCode: %d, request to EC2 IMDS failed", resp.StatusCode)
			if resp.StatusCode >= 500 && attempt < maxAttempts {
				time.Sleep(backoffDelay(attempt))
				continue
			}
			return nil, &credentialsError{msg: prefix + lastErr.Error()}
		}
		role := strings.TrimSpace(strings.SplitN(string(body), "\n", 2)[0])
		if role == "" {
			return nil, &credentialsError{msg: prefix + "no EC2 IMDS role found"}
		}
		req2, _ := http.NewRequestWithContext(ctx, "GET", endpoint+"/latest/meta-data/iam/security-credentials/"+role, nil)
		if token != "" {
			req2.Header.Set("X-Aws-Ec2-Metadata-Token", token)
		}
		resp2, err := client.Do(req2)
		if err != nil {
			return nil, &credentialsError{msg: "get identity: get credentials: failed to refresh cached credentials, failed to load credentials, " + err.Error(), retryable: true}
		}
		b2, _ := io.ReadAll(resp2.Body)
		resp2.Body.Close()
		var cr credsResponse
		if err := decodeJSON(b2, &cr); err != nil || cr.AccessKeyId == "" {
			return nil, &credentialsError{msg: "get identity: get credentials: failed to refresh cached credentials, failed to load credentials, invalid response from EC2 IMDS"}
		}
		return &Credentials{AccessKeyID: cr.AccessKeyId, SecretAccessKey: cr.SecretAccessKey, SessionToken: cr.Token, Source: "EC2RoleProvider"}, nil
	}
	return nil, &credentialsError{msg: prefix + (&MaxAttemptsError{Attempts: maxAttempts, Err: lastErr}).Error(), retryable: true}
}

