		if lk == "user-agent" || lk == "authorization" || lk == "expect" || lk == "accept-encoding" && service != "s3" {
			continue
		}
		headerNames = append(headerNames, lk)
		headerValues[lk] = strings.TrimSpace(strings.Join(v, ","))
	}
	if req.ContentLength > 0 && req.Header.Get("Content-Length") == "" {
		headerNames = append(headerNames, "content-length")
		headerValues["content-length"] = itoa(req.ContentLength)
	}
	sort.Strings(headerNames)
	var canonHeaders strings.Builder
	for _, h := range headerNames {
		canonHeaders.WriteString(h)
		canonHeaders.WriteString(":")
		canonHeaders.WriteString(collapseSpaces(headerValues[h]))
		canonHeaders.WriteString("\n")
	}
	signedHeaders := strings.Join(headerNames, ";")

	path := req.URL.EscapedPath()
	if path == "" {
		path = "/"
	}
	if doubleEncodePath {
		path = uriEncode(path, false)
	}
	canonicalRequest := strings.Join([]string{
		req.Method,
		path,
		canonicalQuery(req.URL.Query()),
		canonHeaders.String(),
		signedHeaders,
		payloadHash,
	}, "\n")

	scope := dateStamp + "/" + region + "/" + service + "/aws4_request"
	stringToSign := strings.Join([]string{
		"AWS4-HMAC-SHA256",
		amzDate,
		scope,
		sha256Hex([]byte(canonicalRequest)),
	}, "\n")

	kDate := hmacSHA256([]byte("AWS4"+creds.SecretAccessKey), dateStamp)
	kRegion := hmacSHA256(kDate, region)
	kService := hmacSHA256(kRegion, service)
	kSigning := hmacSHA256(kService, "aws4_request")
	signature := hex.EncodeToString(hmacSHA256(kSigning, stringToSign))

	req.Header.Set("Authorization", "AWS4-HMAC-SHA256 Credential="+creds.AccessKeyID+"/"+scope+", SignedHeaders="+signedHeaders+", Signature="+signature)
}

func collapseSpaces(s string) string {
	var b strings.Builder
	prevSpace := false
	for _, r := range s {
		if r == ' ' || r == '\t' {
			if !prevSpace {
				b.WriteByte(' ')
			}
			prevSpace = true
			continue
		}
		prevSpace = false
		b.WriteRune(r)
	}
	return b.String()
}

func itoa(n int64) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}
