package awsclient

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"strings"
)

// JSONClient implements the AWS JSON 1.1 RPC protocol.
type JSONClient struct {
	Config       *Config
	ServiceName  string
	ServiceID    string
	SigningName  string
	TargetPrefix string
	EndpointHost string // e.g. "ssm" -> ssm.<region>.amazonaws.com
	// EndpointOverride, if set, takes precedence over the configured endpoints.
	EndpointOverride string
}

// endpointResolutionError is returned when no endpoint can be resolved.
type endpointResolutionError struct {
	msg string
}

func (e *endpointResolutionError) Error() string { return e.msg }

func (c *JSONClient) endpoint() (*url.URL, error) {
	if c.EndpointOverride != "" {
		return parseEndpoint(c.EndpointOverride)
	}
	ep, custom := c.Config.EndpointFor(c.ServiceID, "")
	if custom {
		return parseEndpoint(ep)
	}
	if c.Config.Region == "" {
		return nil, &endpointResolutionError{msg: "failed to resolve service endpoint, endpoint rule error, Invalid Configuration: Missing Region"}
	}
	return url.Parse(fmt.Sprintf("https://%s.%s.amazonaws.com/", c.EndpointHost, c.Config.Region))
}

func parseEndpoint(ep string) (*url.URL, error) {
	if !strings.Contains(ep, "://") {
		ep = "https://" + ep
	}
	u, err := url.Parse(ep)
	if err != nil {
		return nil, &endpointResolutionError{msg: fmt.Sprintf("failed to resolve service endpoint, endpoint rule error, %v", err)}
	}
	if u.Path == "" {
		u.Path = "/"
	}
	return u, nil
}

// parseJSONError decodes an AWS JSON protocol error body.
func parseJSONError(status int, header http.Header, body []byte) *APIError {
	code := header.Get("X-Amzn-Errortype")
	var msg string
	var raw map[string]interface{}
	if err := json.Unmarshal(body, &raw); err == nil {
		for k, v := range raw {
			lk := strings.ToLower(k)
			s, _ := v.(string)
			switch lk {
			case "__type", "code":
				if code == "" {
					code = s
				}
			case "message", "errormessage", "error_message":
				if msg == "" {
					msg = s
				}
			}
		}
	}
	code = sanitizeErrorCode(code)
	return &APIError{Code: code, Message: msg}
}

func sanitizeErrorCode(code string) string {
	if idx := strings.Index(code, ":"); idx >= 0 {
		code = code[:idx]
	}
	if idx := strings.Index(code, "#"); idx >= 0 {
		code = code[idx+1:]
	}
	return code
}

// Call performs a JSON RPC operation.
func (c *JSONClient) Call(ctx context.Context, operation string, input interface{}, output interface{}, modeledErrors []string) error {
	wrap := func(err error) error {
		return &OperationError{Service: c.ServiceName, Operation: operation, Err: err}
	}
	// credentials are resolved before the endpoint, as in the SDK
	if _, err := c.Config.Credentials(ctx); err != nil {
		if isRetryableCredentialsError(err) {
			return wrap(&MaxAttemptsError{Attempts: c.Config.maxAttempts(), Err: err})
		}
		return wrap(err)
	}
	u, err := c.endpoint()
	if err != nil {
		return wrap(err)
	}
	body, err := json.Marshal(input)
	if err != nil {
		return wrap(err)
	}
	if input == nil {
		body = []byte("{}")
	}
	header := http.Header{}
	header.Set("Content-Type", "application/x-amz-json-1.1")
	header.Set("X-Amz-Target", c.TargetPrefix+"."+operation)
	header.Set("Accept-Encoding", "gzip")
	req := &Request{
		ServiceName:   c.ServiceName,
		ServiceID:     c.ServiceID,
		SigningName:   c.SigningName,
		Operation:     operation,
		Method:        "POST",
		URL:           u,
		Header:        header,
		Body:          body,
		ModeledErrors: modeledErrors,
		ParseError:    parseJSONError,
	}
	resp, err := c.Config.Do(ctx, req)
	if err != nil {
		return err
	}
	if output != nil && len(strings.TrimSpace(string(resp.Body))) > 0 {
		if err := json.Unmarshal(resp.Body, output); err != nil {
			var se *json.SyntaxError
			if errors.As(err, &se) {
				return wrap(&DeserializationError{Err: fmt.Errorf("failed to decode response body, %v", err)})
			}
			return wrap(&DeserializationError{Err: err})
		}
	}
	return nil
}
EOF
