package store

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"chamber/awsclient"
)

const (
	// DefaultKeyID is the default KMS key alias used to encrypt secrets.
	DefaultKeyID = "alias/parameter_store_key"

	storeConfigService = "_chamber"
	storeConfigKey     = "store-config"
)

var (
	ssmKeyFormat      = regexp.MustCompile(`^[\w\-\.]+$`)
	ssmFullPathFormat = regexp.MustCompile(`^(/[\w\-\.]+)+$`)
)

// StoreConfig is the (optional) configuration stored in the backend itself.
type StoreConfig struct {
	RequiredTags []string `json:"requiredTags"`
}

// SSMStore stores secrets in AWS Systems Manager Parameter Store.
type SSMStore struct {
	svc        *awsclient.SSM
	kmsKeyID   string
	storeCfg   *StoreConfig
	configRead bool
}

// NewSSMStore creates a new SSM backed store.
func NewSSMStore(ctx context.Context, cfg *awsclient.Config) (*SSMStore, error) {
	endpoint := os.Getenv("CHAMBER_AWS_SSM_ENDPOINT")
	keyID := DefaultKeyID
	if v := os.Getenv("CHAMBER_KMS_KEY_ALIAS"); v != "" {
		keyID = v
	}
	return &SSMStore{
		svc:      awsclient.NewSSM(cfg, endpoint),
		kmsKeyID: keyID,
	}, nil
}

func (s *SSMStore) basePath(service string) string {
	return "/" + service
}

func (s *SSMStore) idToName(id SecretId) string {
	return "/" + id.Service + "/" + id.Key
}

func (s *SSMStore) keyFromName(service, name string) (string, bool) {
	prefix := "/" + service + "/"
	if !strings.HasPrefix(name, prefix) {
		return "", false
	}
	key := name[len(prefix):]
	if !ssmKeyFormat.MatchString(key) {
		return "", false
	}
	return key, true
}

func parseVersion(desc string) int {
	v, err := strconv.Atoi(desc)
	if err != nil {
		return 0
	}
	return v
}

// readStoreConfig fetches the store configuration parameter, if present.
func (s *SSMStore) readStoreConfig(ctx context.Context) (*StoreConfig, error) {
	secret, err := s.readLatest(ctx, SecretId{Service: storeConfigService, Key: storeConfigKey})
	if err != nil {
		if errors.Is(err, ErrSecretNotFound) {
			return &StoreConfig{}, nil
		}
		return nil, err
	}
	var cfg StoreConfig
	if secret.Value != nil {
		if err := json.Unmarshal([]byte(*secret.Value), &cfg); err != nil {
			return nil, fmt.Errorf("failed to unmarshal store config: %w", err)
		}
	}
	return &cfg, nil
}

func (s *SSMStore) Write(ctx context.Context, id SecretId, value string) error {
	return s.WriteWithTags(ctx, id, value, nil)
}

func (s *SSMStore) WriteWithTags(ctx context.Context, id SecretId, value string, tags map[string]string) error {
	version := 1
	current, err := s.readLatest(ctx, id)
	if err != nil && !errors.Is(err, ErrSecretNotFound) {
		return err
	}
	if err == nil {
		version = current.Meta.Version + 1
	}

	if errors.Is(err, ErrSecretNotFound) {
		cfg, cerr := s.readStoreConfig(ctx)
		if cerr != nil {
			return cerr
		}
		var missing []string
		for _, req := range cfg.RequiredTags {
			if _, ok := tags[req]; !ok {
				missing = append(missing, req)
			}
		}
		if len(missing) > 0 {
			return fmt.Errorf("required tags %v are missing", missing)
		}
	} else if len(tags) > 0 {
		return errors.New("tags on write only supported for new secrets")
	}

	_, err = s.svc.PutParameter(ctx, &awsclient.PutParameterInput{
		Description: strconv.Itoa(version),
		KeyId:       s.kmsKeyID,
		Name:        s.idToName(id),
		Overwrite:   true,
		Type:        "SecureString",
		Value:       value,
	})
