			result = append(result, RawSecret{Key: key, Value: p.Value})
		}
		if out.NextToken == "" {
			break
		}
		nextToken = out.NextToken
	}
	return result, nil
}

func (s *SSMStore) ListServices(ctx context.Context, service string, includeSecretName bool) ([]string, error) {
	seen := map[string]bool{}
	var nextToken string
	for {
		out, err := s.svc.DescribeParameters(ctx, &awsclient.DescribeParametersInput{
			MaxResults: 50,
			NextToken:  nextToken,
			ParameterFilters: []awsclient.ParameterFilter{{
				Key:    "Name",
				Option: "BeginsWith",
				Values: []string{"/" + service},
			}},
		})
		if err != nil {
			return nil, err
		}
		for _, p := range out.Parameters {
			if !ssmFullPathFormat.MatchString(p.Name) {
				continue
			}
			if includeSecretName {
				seen[p.Name] = true
			} else {
				svc := strings.TrimPrefix(path.Dir(p.Name), "/")
				seen[svc] = true
			}
		}
		if out.NextToken == "" {
			break
		}
		nextToken = out.NextToken
	}
	result := make([]string, 0, len(seen))
	for k := range seen {
		result = append(result, k)
	}
	sort.Strings(result)
	return result, nil
}

func (s *SSMStore) History(ctx context.Context, id SecretId) ([]ChangeEvent, error) {
	events := []ChangeEvent{}
	var nextToken string
	for {
		out, err := s.svc.GetParameterHistory(ctx, &awsclient.GetParameterHistoryInput{
			Name:           s.idToName(id),
			NextToken:      nextToken,
			WithDecryption: false,
		})
		if err != nil {
			return nil, ErrSecretNotFound
		}
		for _, h := range out.Parameters {
			version := parseVersion(h.Description)
			typ := Updated
			if version == 1 {
				typ = Created
			}
			events = append(events, ChangeEvent{
				Type:    typ,
				Time:    h.LastModifiedDate.Time,
				User:    h.LastModifiedUser,
				Version: version,
			})
		}
		if out.NextToken == "" {
			break
		}
		nextToken = out.NextToken
	}
	return events, nil
}

func (s *SSMStore) Delete(ctx context.Context, id SecretId) error {
	if _, err := s.readLatest(ctx, id); err != nil {
		return err
	}
	return s.svc.DeleteParameter(ctx, &awsclient.DeleteParameterInput{Name: s.idToName(id)})
}
