func parseQueryError(status int, header http.Header, body []byte) *APIError {
	var er queryErrorResponse
	if err := xml.Unmarshal(body, &er); err != nil {
		return &APIError{Code: "UnknownError", Message: "UnknownError"}
	}
	return &APIError{Code: er.Error.Code, Message: er.Error.Message}
}

func (s *STS) endpoint() (*url.URL, error) {
	ep, custom := s.cfg.EndpointFor("sts", "")
	if custom {
		return parseEndpoint(ep)
	}
	if s.cfg.Region == "" {
		return nil, &endpointResolutionError{msg: "failed to resolve service endpoint, endpoint rule error, Invalid Configuration: Missing Region"}
	}
	return url.Parse(fmt.Sprintf("https://sts.%s.amazonaws.com/", s.cfg.Region))
