// GetCallerIdentity returns details about the IAM identity whose credentials
// are used to call the operation.
func (s *STS) GetCallerIdentity(ctx context.Context) (*GetCallerIdentityOutput, error) {
	const op = "GetCallerIdentity"
	wrap := func(err error) error {
		return &OperationError{Service: "STS", Operation: op, Err: err}
	}
	if _, err := s.cfg.Credentials(ctx); err != nil {
		if isRetryableCredentialsError(err) {
			return nil, wrap(&MaxAttemptsError{Attempts: s.cfg.maxAttempts(), Err: err})
		}
		return nil, wrap(err)
	}
	u, err := s.endpoint()
	if err != nil {
		return nil, wrap(err)
	}
	header := http.Header{}
	header.Set("Content-Type", "application/x-www-form-urlencoded")
	header.Set("Accept-Encoding", "gzip")
	body := []byte("Action=GetCallerIdentity&Version=2011-06-15")
	req := &Request{
		ServiceName: "STS",
		ServiceID:   "sts",
		SigningName: "sts",
		Operation:   op,
		Method:      "POST",
		URL:         u,
		Header:      header,
		Body:        body,
		ModeledErrors: []string{
			"ExpiredTokenException", "InvalidIdentityToken", "MalformedPolicyDocument", "PackedPolicyTooLarge", "RegionDisabledException",
		},
		ParseError: parseQueryError,
	}
	resp, err := s.cfg.Do(ctx, req)
	if err != nil {
		return nil, err
	}
	var parsed getCallerIdentityResponse
	if err := xml.Unmarshal(resp.Body, &parsed); err != nil {
		return nil, wrap(&DeserializationError{Err: fmt.Errorf("failed to decode response body, %v", err)})
	}
	return &GetCallerIdentityOutput{
		Account: strings.TrimSpace(parsed.Result.Account),
		Arn:     strings.TrimSpace(parsed.Result.Arn),
		UserId:  strings.TrimSpace(parsed.Result.UserId),
	}, nil
}
