	return s.putLatest(ctx, id.Service, idx)
}

// ---------------------------------------------------------------------------

type s3KMSLatestValue struct {
	Version  int    `json:"version"`
	Value    string `json:"value"`
	KMSAlias string `json:"KMSAlias"`
}

type s3KMSLatestIndex struct {
	Latest map[string]s3KMSLatestValue `json:"latest"`
}

// S3KMSStore stores secrets in S3 using server side KMS encryption.
type S3KMSStore struct {
	S3Store
	kmsKeyAlias string
}

// NewS3KMSStore creates a new S3 (KMS encrypted) backed store.
func NewS3KMSStore(ctx context.Context, cfg *awsclient.Config, bucket string, kmsKeyAlias string) (*S3KMSStore, error) {
	return &S3KMSStore{
		S3Store: S3Store{
			svc:    awsclient.NewS3(cfg),
			sts:    awsclient.NewSTS(cfg),
			bucket: bucket,
		},
		kmsKeyAlias: kmsKeyAlias,
	}, nil
}

func kmsLatestName(alias string) string {
	safe := make([]byte, 0, len(alias))
	for i := 0; i < len(alias); i++ {
		c := alias[i]
		if c == '/' {
			c = '_'
		}
		safe = append(safe, c)
	}
	return "__kms_" + string(safe) + latestObjectName
}

func (s *S3KMSStore) kmsLatestKey(service, alias string) string {
	return service + "/" + kmsLatestName(alias)
}

func (s *S3KMSStore) putObjectKMS(ctx context.Context, key string, body []byte) error {
	return s.svc.PutObject(ctx, &awsclient.PutObjectInput{
		Bucket:               s.bucket,
		Key:                  key,
		Body:                 body,
		ServerSideEncryption: "aws:kms",
		SSEKMSKeyId:          s.kmsKeyAlias,
	})
}

// readAllLatest reads every per-alias latest index for a service and returns
// the merged index as well as the index of the configured alias.
func (s *S3KMSStore) readAllLatest(ctx context.Context, service string) (map[string]s3KMSLatestValue, map[string]*s3KMSLatestIndex, error) {
	keys, err := s.svc.ListObjectsV2(ctx, s.bucket, service+"/__kms")
	if err != nil {
		return nil, nil, err
	}
	sort.Strings(keys)
	merged := map[string]s3KMSLatestValue{}
	perFile := map[string]*s3KMSLatestIndex{}
	for _, k := range keys {
		body, err := s.svc.GetObject(ctx, s.bucket, k)
		if err != nil {
			if isS3NotFound(err) {
				continue
			}
			return nil, nil, err
		}
		var idx s3KMSLatestIndex
		if err := json.Unmarshal(body, &idx); err != nil {
			return nil, nil, err
		}
		if idx.Latest == nil {
			idx.Latest = map[string]s3KMSLatestValue{}
		}
		perFile[k] = &idx
		for key, v := range idx.Latest {
			merged[key] = v
		}
	}
	return merged, perFile, nil
}

func (s *S3KMSStore) Write(ctx context.Context, id SecretId, value string) error {
	_, perFile, err := s.readAllLatest(ctx, id.Service)
	if err != nil {
		return err
	}
	obj, err := s.readObject(ctx, id)
	if err != nil {
		if !errors.Is(err, ErrSecretNotFound) {
			return err
		}
		obj = &s3SecretObject{
			Service: id.Service,
			Key:     "/" + id.Service + "/" + id.Key,
			Values:  map[string]s3SecretValue{},
		}
	}
	identity, err := s.sts.GetCallerIdentity(ctx)
	if err != nil {
		return err
	}
	version := 1
	if latest, ok := latestVersion(obj); ok {
		version = latest.Version + 1
	}
	obj.Values[strconv.Itoa(version)] = s3SecretValue{
		Created:   time.Now().UTC(),
		CreatedBy: identity.Arn,
		Version:   version,
		Value:     value,
	}
	body, err := json.Marshal(obj)
	if err != nil {
		return err
	}
	if err := s.putObjectKMS(ctx, s.objectKey(id), body); err != nil {
		return err
	}
	latestKey := s.kmsLatestKey(id.Service, s.kmsKeyAlias)
	idx := perFile[latestKey]
	if idx == nil {
		idx = &s3KMSLatestIndex{Latest: map[string]s3KMSLatestValue{}}
	}
	idx.Latest[id.Key] = s3KMSLatestValue{Version: version, Value: value, KMSAlias: s.kmsKeyAlias}
	ib, err := json.Marshal(idx)
	if err != nil {
		return err
	}
	return s.putObjectKMS(ctx, latestKey, ib)
}

func (s *S3KMSStore) WriteWithTags(ctx context.Context, id SecretId, value string, tags map[string]string) error {
	if len(tags) > 0 {
		return errors.New("Not implemented for S3 Store")
	}
	return s.Write(ctx, id, value)
}

func (s *S3KMSStore) List(ctx context.Context, service string, includeValues bool) ([]Secret, error) {
	merged, _, err := s.readAllLatest(ctx, service)
	if err != nil {
		return nil, err
	}
	keys := make([]string, 0, len(merged))
	for k := range merged {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	secrets := []Secret{}
	for _, k := range keys {
		obj, err := s.readObject(ctx, SecretId{Service: service, Key: k})
		if err != nil {
			return nil, err
		}
		val, ok := latestVersion(obj)
		if !ok {
			continue
		}
		sec := Secret{Meta: SecretMetadata{Created: val.Created, CreatedBy: val.CreatedBy, Version: val.Version, Key: k}}
		if includeValues {
			v := val.Value
			sec.Value = &v
		}
		secrets = append(secrets, sec)
	}
	return secrets, nil
}

func (s *S3KMSStore) ListRaw(ctx context.Context, service string) ([]RawSecret, error) {
	merged, _, err := s.readAllLatest(ctx, service)
	if err != nil {
		return nil, err
	}
	raw := []RawSecret{}
	for k, v := range merged {
		raw = append(raw, RawSecret{Key: k, Value: v.Value})
	}
	return raw, nil
}

func (s *S3KMSStore) Delete(ctx context.Context, id SecretId) error {
	_, perFile, err := s.readAllLatest(ctx, id.Service)
	if err != nil {
		return err
	}
	if err := s.svc.DeleteObject(ctx, s.bucket, s.objectKey(id)); err != nil {
		return err
	}
	files := make([]string, 0, len(perFile))
	for f := range perFile {
		files = append(files, f)
	}
	sort.Strings(files)
	for _, f := range files {
		idx := perFile[f]
		if _, ok := idx.Latest[id.Key]; !ok {
			continue
		}
		delete(idx.Latest, id.Key)
		ib, err := json.Marshal(idx)
		if err != nil {
			return err
		}
		if err := s.putObjectKMS(ctx, f, ib); err != nil {
			return err
		}
	}
	return nil
}

var _ Store = (*S3Store)(nil)
var _ Store = (*S3KMSStore)(nil)
var _ Store = (*SSMStore)(nil)
var _ Store = (*SecretsManagerStore)(nil)
var _ Store = (*NullStore)(nil)

func init() {
	_ = fmt.Sprintf
}
EOF
