func read(cmd *cobra.Command, args []string) error {
	service := utils.NormalizeService(args[0])
	if err := utils.ValidateService(service); err != nil {
		return fmt.Errorf("Failed to validate service: %w", err)
	}

	key := utils.NormalizeKey(args[1])
	if err := utils.ValidateKey(key); err != nil {
		return fmt.Errorf("Failed to validate key: %w", err)
	}

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}

	secretId := store.SecretId{
		Service: service,
		Key:     key,
	}

	secret, err := secretStore.Read(context.Background(), secretId, readVersion)
	if err != nil {
		return fmt.Errorf("Failed to read: %w", err)
	}

	value := ""
	if secret.Value != nil {
		value = *secret.Value
	}

