	"github.com/spf13/cobra"

	"chamber/store"
	"chamber/utils"
)

var (
	singleline    bool
	skipUnchanged bool
	writeTags     map[string]string
)

var writeCmd = &cobra.Command{
	Use:   "write <service> <key> [--] <value|->",
	Short: "write a secret",
	Args:  cobra.ExactArgs(3),
	RunE:  write,
}

func init() {
	writeCmd.Flags().BoolVarP(&singleline, "singleline", "s", false, "Insert single line parameter (end with \\n)")
	writeCmd.Flags().BoolVar(&skipUnchanged, "skip-unchanged", false, "Skip writing secret if value is unchanged")
	writeCmd.Flags().StringToStringVarP(&writeTags, "tags", "t", map[string]string{}, "Add tags to the secret; new secrets only")
	RootCmd.AddCommand(writeCmd)
}

func write(cmd *cobra.Command, args []string) error {
	service := utils.NormalizeService(args[0])
	if err := utils.ValidateService(service); err != nil {
		return fmt.Errorf("Failed to validate service: %w", err)
	}

	key := utils.NormalizeKey(args[1])
	if err := utils.ValidateKey(key); err != nil {
		return fmt.Errorf("Failed to validate key: %w", err)
	}

	value := args[2]
	if value == "-" {
		// read from stdin
		v, err := getValue()
		if err != nil {
			return err
		}
		value = v
	}

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}

	secretId := store.SecretId{
		Service: service,
		Key:     key,
	}

	if skipUnchanged {
		currentSecret, err := secretStore.Read(context.Background(), secretId, -1)
		if err == nil && currentSecret.Value != nil && value == *currentSecret.Value {
			return nil
		}
	}

	if len(writeTags) > 0 {
		return secretStore.WriteWithTags(context.Background(), secretId, value, writeTags)
	}
	return secretStore.Write(context.Background(), secretId, value)
}

func getValue() (string, error) {
	if singleline {
		buf := bufio.NewReader(os.Stdin)
		v, err := buf.ReadString('\n')
		if err != nil {
			return "", err
		}
		return strings.TrimSuffix(v, "\n"), nil
	}
	v, err := io.ReadAll(os.Stdin)
	if err != nil {
		return "", err
	}
	return string(v), nil
}
