// sanitizeEnvKey replaces characters that are not valid in an environment
// variable name.
func sanitizeEnvKey(key string) string {
	key = strings.ReplaceAll(key, "-", "_")
	key = strings.ReplaceAll(key, ".", "_")
	return key
}

var shellUnsafe = regexp.MustCompile(`[^\w@%+=:,./-]`)

// shellQuote quotes a string so that it is safe to use in a POSIX shell.
func shellQuote(s string) string {
	if len(s) == 0 {
		return "''"
	}
	if shellUnsafe.MatchString(s) {
		return "'" + strings.ReplaceAll(s, "'", `'"'"'`) + "'"
	}
	return s
}

var doubleQuoteReplacer = strings.NewReplacer(
	`\`, `\\`,
	`"`, `\"`,
	`$`, `\$`,
	"`", "\\`",
	"\n", `\n`,
	"\r", `\r`,
)

// doubleQuoteEscape escapes a value for use inside double quotes.
func doubleQuoteEscape(s string) string {
	return doubleQuoteReplacer.Replace(s)
}
