--pristine takes effect after checking for --strict values

	$ HOME=/tmp DB_USERNAME=chamberme DB_PASSWORD=chamberme chamber exec --strict --pristine service exec -- env
	DB_USERNAME=root
	DB_PASSWORD=hunter22
`,
}

func init() {
	execCmd.Flags().BoolVar(&pristine, "pristine", false, "only use variables retrieved from the backend; do not inherit existing environment variables")
	execCmd.Flags().BoolVar(&strict, "strict", false, `enable strict mode:
only inject secrets for which there is a corresponding env var with value
<strict-value>, and fail if there are any env vars with that value missing
from secrets`)
	execCmd.Flags().StringVar(&strictValue, "strict-value", "chamberme", "value to expect in --strict mode")
	RootCmd.AddCommand(execCmd)
}

// environ is a slice of "KEY=VALUE" strings with helpers to manipulate it.
type environ []string

func (e environ) index(key string) int {
	prefix := key + "="
	for i, kv := range e {
		if strings.HasPrefix(kv, prefix) {
			return i
		}
	}
	return -1
}

// IsSet reports whether the key is present.
func (e environ) IsSet(key string) bool {
	return e.index(key) >= 0
}

// Set sets the key to the value, replacing an existing entry in place.
func (e *environ) Set(key, val string) {
	kv := key + "=" + val
	if i := e.index(key); i >= 0 {
		(*e)[i] = kv
		return
	}
	*e = append(*e, kv)
}

// Map returns the environment as a map.
func (e environ) Map() map[string]string {
	m := make(map[string]string, len(e))
	for _, kv := range e {
		parts := strings.SplitN(kv, "=", 2)
		if len(parts) == 2 {
			m[parts[0]] = parts[1]
		} else {
			m[parts[0]] = ""
		}
	}
	return m
}

func execRun(cmd *cobra.Command, args []string) error {
	dashIx := cmd.ArgsLenAtDash()
	services, command, commandArgs := args[:dashIx], args[dashIx], args[dashIx+1:]

	for _, service := range services {
		if err := utils.ValidateServiceWithLabel(service); err != nil {
			return fmt.Errorf("Failed to validate service: %w", err)
		}
	}

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}

	parentEnv := environ(os.Environ())
	env := environ(append([]string(nil), parentEnv...))

	// in strict mode, the variables of the parent env having the strict
	// value are the ones expected to be filled from the store
	var expected map[string]bool
	var expectedOrder []string
	if strict {
		slog.Debug("chamber: strict mode engaged")
		expected = map[string]bool{}
		for _, kv := range parentEnv {
			parts := strings.SplitN(kv, "=", 2)
			if len(parts) == 2 && parts[1] == strictValue {
				expected[parts[0]] = false
				expectedOrder = append(expectedOrder, parts[0])
			}
		}
	}

	if pristine {
		slog.Debug("chamber: pristine mode engaged")
		pristineEnv := environ{}
		if strict {
			for _, k := range expectedOrder {
				pristineEnv.Set(k, strictValue)
			}
		}
		env = pristineEnv
	}

	for _, service := range services {
		normalized := utils.NormalizeService(service)
		rawSecrets, err := secretStore.ListRaw(context.Background(), normalized)
		if err != nil {
			return fmt.Errorf("Failed to list store contents: %w", err)
		}
		collected := map[string]string{}
		for _, rawSecret := range rawSecrets {
			collected[rawSecret.Key] = rawSecret.Value
		}
		for key, value := range collected {
			envVarKey := strings.ToUpper(utils.Key(key))
			envVarKey = strings.ReplaceAll(envVarKey, "-", "_")
			if strict {
				if _, ok := expected[envVarKey]; !ok {
					continue
				}
				expected[envVarKey] = true
			} else if env.IsSet(envVarKey) {
				fmt.Fprintf(os.Stderr, "warning: service %s overwriting environment variable %s\n", service, envVarKey)
			}
			env.Set(envVarKey, value)
		}
	}

	if strict {
		for _, k := range expectedOrder {
			if !expected[k] {
				return fmt.Errorf("parent env was expecting %s=%s, but was not in store", k, strictValue)
			}
		}
	}

	if verbose {
		slog.Debug(fmt.Sprintf("info: With environment %s\n", strings.Join(env, ",")))
	}

	path, err := exec.LookPath(command)
	if err != nil {
		return err
	}
	return syscall.Exec(path, append([]string{command}, commandArgs...), env)
}
