func tagSecretId(args []string) (store.SecretId, error) {
	service := utils.NormalizeService(args[0])
	if err := utils.ValidateService(service); err != nil {
		return store.SecretId{}, fmt.Errorf("Failed to validate service: %w", err)
	}
	key := utils.NormalizeKey(args[1])
	if err := utils.ValidateKey(key); err != nil {
		return store.SecretId{}, fmt.Errorf("Failed to validate key: %w", err)
	}
	return store.SecretId{Service: service, Key: key}, nil
}

func tagRead(cmd *cobra.Command, args []string) error {
	secretId, err := tagSecretId(args)
	if err != nil {
		return err
	}

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}

	tags, err := secretStore.ReadTags(context.Background(), secretId)
	if err != nil {
		return fmt.Errorf("Failed to read tags: %w", err)
	}

	w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
	fmt.Fprintln(w, "Key\tValue")
	for k, v := range tags {
		fmt.Fprintf(w, "%s\t%s\n", k, v)
	}
	w.Flush()
	return nil
}

type tagPair struct {
	key   string
	value string
}

func tagWrite(cmd *cobra.Command, args []string) error {
	secretId, err := tagSecretId(args)
	if err != nil {
		return err
	}

	var pairs []tagPair
	tags := map[string]string{}
	for _, tag := range args[2:] {
		parts := strings.SplitN(tag, "=", 2)
		if len(parts) != 2 {
			return fmt.Errorf("Failed to parse tag %s: tag must be in the form key=value", tag)
