		if err := utils.ValidateTag(parts[0], parts[1]); err != nil {
			return fmt.Errorf("Failed to validate tag with key %s: %w", parts[0], err)
		}
		pairs = append(pairs, tagPair{key: parts[0], value: parts[1]})
		tags[parts[0]] = parts[1]
	}

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}

	if err := secretStore.WriteTags(context.Background(), secretId, tags, deleteOtherTags); err != nil {
		return fmt.Errorf("Failed to write tags: %w", err)
	}

	w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
	fmt.Fprintln(w, "Key\tValue")
	for _, p := range pairs {
		fmt.Fprintf(w, "%s\t%s\n", p.key, p.value)
	}
	w.Flush()
	return nil
}

func tagDelete(cmd *cobra.Command, args []string) error {
	secretId, err := tagSecretId(args)
	if err != nil {
		return err
	}

	tagKeys := args[2:]
	for _, k := range tagKeys {
		if err := utils.ValidateTagKey(k); err != nil {
			return fmt.Errorf("Failed to validate tag key %s: %w", k, err)
		}
	}

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}

	if err := secretStore.DeleteTags(context.Background(), secretId, tagKeys); err != nil {
		return fmt.Errorf("Failed to delete tags: %w", err)
	}
	return nil
}
