	"n": true, "N": true, "no": true, "No": true, "NO": true,
	"on": true, "On": true, "ON": true,
	"off": true, "Off": true, "OFF": true,
}

var timeLayouts = []string{
	time.RFC3339,
	"2006-01-02T15:04:05.999999999Z07:00",
	"2006-01-02t15:04:05.999999999Z07:00",
	"2006-01-02 15:04:05.999999999",
	"2006-01-02",
	"15:4",
}

func looksLikeTimeValue(v string) bool {
	for _, layout := range timeLayouts {
		if _, err := time.Parse(layout, v); err == nil {
			return true
		}
	}
	return false
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func isHexDigit(c byte) bool {
	return isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

// matchDigits reports whether s consists of digits accepted by pred (plus
// underscores) and contains at least one digit.
func matchDigits(s string, pred func(byte) bool) bool {
	digits := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '_' {
			continue
		}
		if !pred(c) {
			return false
		}
		digits++
	}
	return digits > 0
}

type numberKind int

const (
	notNumber numberKind = iota
	intNumber
	floatNumber
	hexNumber
	octalNumber
	binaryNumber
)

// numberStat classifies a plain scalar as a YAML number.
func numberStat(s string) numberKind {
	if s == "" || s == "-" || s == "." || s == "+" || s == "_" {
		return notNumber
	}
	if s[0] == '_' {
		return notNumber
	}
	i := 0
	if s[i] == '-' || s[i] == '+' {
		i++
		if s[0] == '+' && i < len(s) && s[i] == '-' {
			i++
		}
	}
	rest := s[i:]
	if rest == "" {
		return notNumber
	}
	if strings.HasPrefix(rest, "0x") {
		if matchDigits(rest[2:], isHexDigit) {
			return hexNumber
		}
		return notNumber
	}
	if strings.HasPrefix(rest, "0o") {
		if matchDigits(rest[2:], func(c byte) bool { return c >= '0' && c <= '7' }) {
			return octalNumber
		}
		return notNumber
	}
	if strings.HasPrefix(rest, "0b") {
		if matchDigits(rest[2:], func(c byte) bool { return c == '0' || c == '1' }) {
			return binaryNumber
		}
		return notNumber
	}
	j := 0
	intDigits := 0
	for j < len(rest) && (isDigit(rest[j]) || rest[j] == '_') {
		if isDigit(rest[j]) {
			intDigits++
		}
		j++
	}
	dot := false
	fracDigits := 0
	if j < len(rest) && rest[j] == '.' {
		dot = true
		j++
		for j < len(rest) && (isDigit(rest[j]) || rest[j] == '_') {
			if isDigit(rest[j]) {
				fracDigits++
			}
			j++
		}
	}
	if intDigits+fracDigits == 0 {
		return notNumber
	}
	exp := false
	if j < len(rest) && (rest[j] == 'e' || rest[j] == 'E') {
		if !dot {
			return notNumber
		}
		exp = true
		j++
		if j < len(rest) && (rest[j] == '+' || rest[j] == '-') {
			j++
		}
		expDigits := 0
		for j < len(rest) && isDigit(rest[j]) {
			expDigits++
			j++
		}
		if expDigits == 0 {
			return notNumber
		}
	}
	if j != len(rest) {
		return notNumber
	}
	if dot || exp {
		return floatNumber
	}
	if len(rest) > 1 && rest[0] == '0' {
		for k := 0; k < len(rest); k++ {
			if rest[k] == '8' || rest[k] == '9' {
				return notNumber
			}
		}
		return octalNumber
	}
	return intNumber
}

// IsNeedQuoted reports whether a plain scalar needs quoting when encoded.
func IsNeedQuoted(v string) bool {
	if v == "" {
		return true
	}
	if reservedEncKeywords[v] {
		return true
	}
	if numberStat(v) != notNumber {
		return true
	}
	if v == "-" {
		return true
	}
	switch v[0] {
	case '*', '&', '[', '{', '}', ']', ',', '!', '|', '>', '%', '\'', '"', '@', ' ', '`', '#':
		return true
	}
	switch v[len(v)-1] {
	case ':', ' ':
		return true
	}
	if looksLikeTimeValue(v) {
		return true
	}
	for i := 0; i < len(v); i++ {
		switch v[i] {
		case '#', '\\':
			return true
		case ':', '-':
			if i+1 < len(v) && v[i+1] == ' ' {
				return true
			}
		}
	}
	return false
}

func detectLineBreakCharacter(s string) string {
	nc := strings.Count(s, "\n")
	rc := strings.Count(s, "\r")
	rnc := strings.Count(s, "\r\n")
	switch {
	case nc == rnc && rc == rnc:
		return "\r\n"
	case rc > nc:
		return "\r"
	default:
		return "\n"
	}
}

func literalBlockHeader(v, lbc string) string {
	switch {
	case !strings.Contains(v, lbc):
		return ""
	case strings.HasSuffix(v, lbc+lbc):
		return "|+"
	case strings.HasSuffix(v, lbc):
		return "|"
	default:
		return "|-"
	}
}

// encodeScalar encodes a string scalar for use as a mapping value at the
// given indentation.
func encodeScalar(v string, indent string) string {
	if IsNeedQuoted(v) {
		return strconv.Quote(v)
	}
	lbc := detectLineBreakCharacter(v)
	if strings.Contains(v, lbc) {
		header := literalBlockHeader(v, lbc)
		parts := strings.Split(v, lbc)
		for i := range parts {
			parts[i] = indent + parts[i]
		}
		block := strings.Join(parts, lbc)
		block = strings.TrimSuffix(block, lbc+indent)
		block = strings.TrimSuffix(block, indent)
		return header + lbc + block
	}
	if len(v) > 0 && (v[0] == '{' || v[0] == '[') {
		return "'" + v + "'"
	}
	return v
}

// EncodeStringMap encodes a flat string map as a YAML document.
func EncodeStringMap(m map[string]string) string {
	if len(m) == 0 {
		return "{}\n"
	}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	for _, k := range keys {
		b.WriteString(encodeScalar(k, "  "))
		b.WriteString(": ")
		b.WriteString(encodeScalar(m[k], "  "))
		b.WriteString("\n")
	}
	return b.String()
}
