func (p *parser) hasPrefix(s string) bool {
	rs := []rune(s)
	if p.pos+len(rs) > len(p.src) {
		return false
	}
	for i, r := range rs {
		if p.src[p.pos+i] != r {
			return false
		}
	}
	return true
}

// lineIsMappingEntry checks whether the content starting at the current
// position (on the current line) is a block mapping entry ("key: value").
// It returns the end position of the key and the position of the ':'.
func (p *parser) findMappingIndicator() (keyEnd int, colonPos int, ok bool) {
	i := p.pos
	if i >= len(p.src) {
		return 0, 0, false
	}
	r := p.src[i]
	if r == '"' || r == '\'' {
		// quoted key
		q := r
		i++
		for i < len(p.src) {
			if p.src[i] == '\\' && q == '"' {
				i += 2
				continue
			}
			if p.src[i] == q {
				if q == '\'' && i+1 < len(p.src) && p.src[i+1] == '\'' {
					i += 2
					continue
				}
				break
			}
			if p.src[i] == '\n' {
				return 0, 0, false
			}
			i++
		}
		if i >= len(p.src) {
			return 0, 0, false
		}
		i++ // closing quote
		keyEnd = i
		for i < len(p.src) && (p.src[i] == ' ' || p.src[i] == '\t') {
			i++
		}
		if i < len(p.src) && p.src[i] == ':' && (i+1 >= len(p.src) || isWhite(p.src[i+1])) {
			return keyEnd, i, true
		}
		return 0, 0, false
	}
	if r == '[' || r == '{' || r == '-' && isWhite(safeRune(p.src, i+1)) || r == '#' {
		return 0, 0, false
	}
	// plain key: scan to ": " or ":" EOL (not inside the line)
	for i < len(p.src) && p.src[i] != '\n' {
		if p.src[i] == ':' && (i+1 >= len(p.src) || isWhite(p.src[i+1])) {
			// key is text before, trimmed
			return i, i, true
		}
		if p.src[i] == '#' && i > 0 && (p.src[i-1] == ' ' || p.src[i-1] == '\t') {
			return 0, 0, false
		}
		i++
	}
	return 0, 0, false
}

func safeRune(src []rune, i int) rune {
	if i < 0 || i >= len(src) {
		return 0
	}
	return src[i]
}

// parseBlockNode parses a node in block context whose indentation must be
// greater than parentIndent.
func (p *parser) parseBlockNode(parentIndent int, root bool) (*node, error) {
	if err := p.skipBlankLines(); err != nil {
		return nil, err
	}
	if p.eof() {
		return &node{kind: nullNode, line: p.line, col: p.col}, nil
	}
	indent := p.lineIndent()
	if indent <= parentIndent {
		return &node{kind: nullNode, line: p.line, col: p.col}, nil
	}
	// move to the first content character
	for i := 0; i < indent; i++ {
		p.advance()
	}
	return p.parseNodeAt(indent, parentIndent)
}

// parseNodeAt parses the node starting at the current (content) position on
// a line with the given indentation.
func (p *parser) parseNodeAt(indent int, parentIndent int) (*node, error) {
	r := p.peek()
	// properties (tags / anchors)
	tag := ""
	for r == '!' || r == '&' {
		start := p.pos
		for !p.eof() && !isWhite(p.peek()) {
			p.advance()
		}
		prop := string(p.src[start:p.pos])
		if strings.HasPrefix(prop, "!") {
			tag = prop
		}
		p.skipSpaces()
		if p.peek() == '\n' || p.eof() || p.peek() == '#' {
			p.skipComment()
			// value on the following lines
			n, err := p.parseBlockNode(indent-1+0, false)
			if err != nil {
				return nil, err
			}
			if n.kind == nullNode {
				// e.g. "!!str" alone -> empty string
				n = &node{kind: scalarNode, line: n.line, col: n.col, value: "", tag: tag}
			}
			n.tag = tag
			return n, nil
		}
		r = p.peek()
	}
	if r == '-' && isWhite(p.peekAt(1)) {
		n, err := p.parseBlockSequence(indent)
		if err != nil {
			return nil, err
		}
		n.tag = tag
		return n, nil
	}
	if _, _, ok := p.findMappingIndicator(); ok {
		n, err := p.parseBlockMapping(indent)
		if err != nil {
			return nil, err
		}
		n.tag = tag
		return n, nil
	}
	n, err := p.parseInlineValue(indent, parentIndent, false)
	if err != nil {
		return nil, err
	}
	n.tag = tag
	return n, nil
}

// parseBlockMapping parses a block mapping whose keys are at the given
// indentation.
func (p *parser) parseBlockMapping(indent int) (*node, error) {
	m := &node{kind: mappingNode, line: p.line, col: p.col}
	first := true
	seen := map[string]*node{}
	for {
		keyEnd, colonPos, ok := p.findMappingIndicator()
		if !ok {
			return nil, p.errorf(p.line, p.col, "non-map value is specified")
		}
		keyLine, keyCol := p.line, p.col
		var key *node
		if p.peek() == '"' || p.peek() == '\'' {
			k, err := p.parseQuotedScalar()
			if err != nil {
				return nil, err
			}
			key = k
			_ = keyEnd
		} else {
			raw := string(p.src[p.pos:keyEnd])
			for p.pos < keyEnd {
				p.advance()
			}
			key = &node{kind: scalarNode, line: keyLine, col: keyCol, value: strings.TrimRight(raw, " \t"), style: plainStyle}
