			return nil, p.errorf(keyLine, keyCol, "mapping key %q already defined at [%d:%d]", keyStr, prev.line, prev.col)
		}
		seen[keyStr] = key

		p.skipSpaces()
		var val *node
		if p.peek() == '#' || p.peek() == '\n' || p.eof() {
			p.skipComment()
			if !p.eof() {
				p.advance() // newline
			}
			// value on following lines
			if err := p.skipBlankLines(); err != nil {
				return nil, err
			}
			nextIndent := p.lineIndent()
			if !p.eof() && nextIndent == indent && p.lineStartsWithSeqEntry() {
				for i := 0; i < indent; i++ {
					p.advance()
				}
				v, err := p.parseBlockSequence(indent)
				if err != nil {
					return nil, err
				}
				val = v
			} else {
				v, err := p.parseBlockNode(indent, false)
				if err != nil {
					return nil, err
				}
				val = v
			}
		} else {
			v, err := p.parseInlineValue(indent, indent, true)
			if err != nil {
				return nil, err
			}
			val = v
		}
		m.keys = append(m.keys, key)
		m.vals = append(m.vals, val)

		// next entry?
		if err := p.skipBlankLines(); err != nil {
			return nil, err
		}
		if p.eof() {
			return m, nil
		}
		nextIndent := p.lineIndent()
		if nextIndent < indent {
			return m, nil
		}
		if p.col == 1 && indent == 0 && (p.hasPrefix("---") || p.hasPrefix("...")) && isWhite(p.peekAt(3)) {
			return m, nil
		}
		if nextIndent > indent {
			for i := 0; i < nextIndent; i++ {
				p.advance()
			}
			return nil, p.errorf(p.line, p.col, "value is not allowed in this context")
		}
		for i := 0; i < indent; i++ {
			p.advance()
		}
	}
}

func (p *parser) lineStartsWithSeqEntry() bool {
	i := p.pos
	for i < len(p.src) && p.src[i] == ' ' {
		i++
	}
	return i < len(p.src) && p.src[i] == '-' && isWhite(safeRune(p.src, i+1))
}

// parseBlockSequence parses a block sequence whose entries are at the given
// indentation.
func (p *parser) parseBlockSequence(indent int) (*node, error) {
	s := &node{kind: sequenceNode, line: p.line, col: p.col}
	for {
		if !(p.peek() == '-' && isWhite(p.peekAt(1))) {
			return nil, p.errorf(p.line, p.col, "value is not allowed in this context")
		}
		p.advance() // '-'
		p.skipSpaces()
		var item *node
		if p.peek() == '#' || p.peek() == '\n' || p.eof() {
			p.skipComment()
			if !p.eof() {
				p.advance()
			}
			v, err := p.parseBlockNode(indent, false)
			if err != nil {
				return nil, err
			}
			item = v
		} else {
			// the item content defines a new indentation level
			itemIndent := p.col - 1
			v, err := p.parseNodeAt(itemIndent, indent)
			if err != nil {
				return nil, err
			}
			item = v
		}
		s.items = append(s.items, item)
		if err := p.skipBlankLines(); err != nil {
			return nil, err
		}
		if p.eof() {
			return s, nil
		}
		nextIndent := p.lineIndent()
		if nextIndent < indent {
			return s, nil
		}
		if nextIndent > indent {
			for i := 0; i < nextIndent; i++ {
				p.advance()
			}
			return nil, p.errorf(p.line, p.col, "value is not allowed in this context")
		}
		for i := 0; i < indent; i++ {
			p.advance()
		}
		if !(p.peek() == '-' && isWhite(p.peekAt(1))) {
			return s, nil
		}
	}
}

// parseInlineValue parses a value that starts on the current line: a flow
// collection, a quoted scalar, a block scalar or a plain scalar.
func (p *parser) parseInlineValue(indent int, parentIndent int, isMapValue bool) (*node, error) {
	r := p.peek()
	tag := ""
	for r == '!' || r == '&' {
		start := p.pos
		for !p.eof() && !isWhite(p.peek()) {
			p.advance()
		}
		prop := string(p.src[start:p.pos])
		if strings.HasPrefix(prop, "!") {
			tag = prop
		}
		p.skipSpaces()
		if p.peek() == '\n' || p.eof() || p.peek() == '#' {
			p.skipComment()
			if !p.eof() {
				p.advance()
			}
			n, err := p.parseBlockNode(parentIndent, false)
			if err != nil {
				return nil, err
			}
			if n.kind == nullNode {
				n = &node{kind: scalarNode, line: n.line, col: n.col, value: ""}
			}
			n.tag = tag
			return n, nil
		}
		r = p.peek()
	}
	var n *node
	var err error
	switch {
	case r == '{' || r == '[':
		n, err = p.parseFlowNode()
		if err != nil {
			return nil, err
		}
		if err := p.endOfLine(); err != nil {
			return nil, err
		}
	case r == '"' || r == '\'':
		n, err = p.parseQuotedScalar()
		if err != nil {
			return nil, err
		}
		if err := p.endOfLine(); err != nil {
			return nil, err
		}
	case r == '|' || r == '>':
		n, err = p.parseBlockScalar(parentIndent)
		if err != nil {
			return nil, err
		}
	case r == '*':
		return nil, p.errorf(p.line, p.col, "anchors and aliases are not supported")
	default:
		n, err = p.parsePlainScalar(parentIndent, isMapValue)
		if err != nil {
			return nil, err
		}
	}
	n.tag = tag
	return n, nil
}

// endOfLine consumes trailing spaces and a comment; the next character must be
// a newline or EOF.
func (p *parser) endOfLine() error {
	p.skipSpaces()
	p.skipComment()
	if p.eof() {
		return nil
	}
	if p.peek() == '\n' {
		p.advance()
		return nil
	}
	return p.errorf(p.line, p.col, "value is not allowed in this context")
}

// parsePlainScalar parses a plain (unquoted) scalar, possibly spanning
// multiple lines.
func (p *parser) parsePlainScalar(parentIndent int, isMapValue bool) (*node, error) {
	n := &node{kind: scalarNode, line: p.line, col: p.col, style: plainStyle}
	var lines []string
	readLine := func() string {
		start := p.pos
		end := p.pos
		for !p.eof() && p.peek() != '\n' {
			r := p.peek()
			if r == '#' && p.pos > start && (p.src[p.pos-1] == ' ' || p.src[p.pos-1] == '\t') {
				break
			}
			if r == ':' && isWhite(p.peekAt(1)) && isMapValue {
				// a mapping indicator inside a value is not allowed in block context
				break
			}
			p.advance()
			if r != ' ' && r != '\t' {
				end = p.pos
			}
		}
		return string(p.src[start:end])
	}
	first := readLine()
	lines = append(lines, first)
	if !p.eof() && p.peek() == ':' && isWhite(p.peekAt(1)) {
		return nil, p.errorf(p.line, p.col, "mapping value is not allowed in this context")
	}
	// consume comment / newline
	p.skipSpaces()
	p.skipComment()
	if !p.eof() && p.peek() == '\n' {
		p.advance()
	}
	// continuation lines
	for !p.eof() {
		save := p.save()
		blank := 0
		for !p.eof() {
			s2 := p.save()
			p.skipSpaces()
			if p.peek() == '\n' {
				p.advance()
				blank++
				continue
			}
			p.restore(s2)
			break
		}
		if p.eof() {
			p.restore(save)
			break
		}
		ind := p.lineIndent()
		if ind <= parentIndent {
			p.restore(save)
			break
		}
		s3 := p.save()
		for i := 0; i < ind; i++ {
			p.advance()
		}
		r := p.peek()
		if r == '#' || (r == '-' && isWhite(p.peekAt(1))) || (p.col == 1 && (p.hasPrefix("---") || p.hasPrefix("...")) && isWhite(p.peekAt(3))) {
			p.restore(save)
			break
		}
		if _, _, ok := p.findMappingIndicator(); ok {
			p.restore(save)
			break
		}
		_ = s3
		text := readLine()
		if blank > 0 {
			lines = append(lines, strings.Repeat("\n", blank)+text)
		} else {
			lines = append(lines, " "+text)
		}
		p.skipSpaces()
		p.skipComment()
		if !p.eof() && p.peek() == '\n' {
			p.advance()
		}
	}
	// fold
	var b strings.Builder
	for i, l := range lines {
		if i == 0 {
			b.WriteString(l)
			continue
		}
		if strings.HasPrefix(l, "\n") {
			b.WriteString(l)
		} else {
			b.WriteString(l)
		}
	}
	n.value = b.String()
	return n, nil
}

// parseQuotedScalar parses a single or double quoted scalar.
func (p *parser) parseQuotedScalar() (*node, error) {
	q := p.peek()
	n := &node{kind: scalarNode, line: p.line, col: p.col}
	if q == '"' {
		n.style = doubleQuotedStyle
	} else {
		n.style = singleQuotedStyle
	}
	p.advance()
	var b strings.Builder
	for {
		if p.eof() {
			if q == '"' {
				return nil, p.errorf(n.line, n.col, "could not find end character of double-quoted text")
			}
			return nil, p.errorf(n.line, n.col, "could not find end character of single-quoted text")
		}
		r := p.advance()
		if r == q {
			if q == '\'' && p.peek() == '\'' {
				p.advance()
				b.WriteRune('\'')
				continue
			}
			break
		}
		if r == '\\' && q == '"' {
			if p.eof() {
				continue
			}
			e := p.advance()
			switch e {
			case 'n':
				b.WriteByte('\n')
			case 't', '\t':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '\\':
				b.WriteByte('\\')
			case '"':
				b.WriteByte('"')
			case '/':
				b.WriteByte('/')
			case '\'':
				b.WriteByte('\'')
			case '0':
				b.WriteByte(0)
			case 'a':
				b.WriteByte('\a')
			case 'b':
				b.WriteByte('\b')
			case 'f':
				b.WriteByte('\f')
			case 'v':
				b.WriteByte('\v')
			case 'e':
				b.WriteByte(0x1b)
			case ' ':
				b.WriteByte(' ')
			case 'N':
				b.WriteString("\u0085")
			case '_':
				b.WriteString("\u00a0")
			case 'L':
				b.WriteString("\u2028")
			case 'P':
				b.WriteString("\u2029")
			case 'x', 'u', 'U':
				width := map[rune]int{'x': 2, 'u': 4, 'U': 8}[e]
				var hex []rune
				for i := 0; i < width && !p.eof(); i++ {
					hex = append(hex, p.advance())
				}
				v, err := strconv.ParseUint(string(hex), 16, 32)
				if err != nil {
					return nil, p.errorf(n.line, n.col, "invalid escape sequence")
				}
				b.WriteRune(rune(v))
			case '\n':
				// escaped line break: skip leading whitespace of next line
				for !p.eof() && (p.peek() == ' ' || p.peek() == '\t') {
					p.advance()
				}
			default:
				b.WriteByte('\\')
				b.WriteRune(e)
			}
			continue
		}
		if r == '\n' {
			// line folding
			blank := 0
			for {
				for !p.eof() && (p.peek() == ' ' || p.peek() == '\t') {
					p.advance()
				}
				if !p.eof() && p.peek() == '\n' {
					p.advance()
					blank++
					continue
				}
				break
			}
			// trim trailing spaces of the previous content
			s := strings.TrimRight(b.String(), " \t")
			b.Reset()
			b.WriteString(s)
			if blank == 0 {
				b.WriteByte(' ')
			} else {
				b.WriteString(strings.Repeat("\n", blank))
			}
			continue
		}
		b.WriteRune(r)
	}
	n.value = b.String()
	return n, nil
}

// parseBlockScalar parses a literal (|) or folded (>) block scalar.
func (p *parser) parseBlockScalar(parentIndent int) (*node, error) {
	n := &node{kind: scalarNode, line: p.line, col: p.col}
	ind := p.advance()
	if ind == '|' {
		n.style = literalStyle
	} else {
		n.style = foldedStyle
	}
	chomp := "clip"
	explicit := 0
	for !p.eof() && p.peek() != '\n' && p.peek() != ' ' && p.peek() != '#' {
		r := p.advance()
		switch {
		case r == '-':
			chomp = "strip"
		case r == '+':
			chomp = "keep"
		case r >= '1' && r <= '9':
			explicit = int(r - '0')
		default:
			return nil, p.errorf(p.line, p.col-1, "invalid block scalar header")
		}
	}
	p.skipSpaces()
	p.skipComment()
	if !p.eof() && p.peek() == '\n' {
		p.advance()
	}
	// determine content indentation
	contentIndent := -1
	if explicit > 0 {
		contentIndent = parentIndent + explicit
		if parentIndent < 0 {
			contentIndent = explicit
		}
	}
	var rawLines []string
	for !p.eof() {
		save := p.save()
		ind := p.lineIndent()
		// is the line blank?
		i := p.pos + ind
		blank := i >= len(p.src) || p.src[i] == '\n'
		if blank {
			rawLines = append(rawLines, "")
			if contentIndent >= 0 && ind > contentIndent {
				rawLines[len(rawLines)-1] = strings.Repeat(" ", ind-contentIndent)
			}
			p.skipToNextLine()
			continue
		}
		if contentIndent < 0 {
			if ind <= parentIndent {
				p.restore(save)
				break
			}
			contentIndent = ind
		}
		if ind < contentIndent {
			p.restore(save)
			break
		}
		for k := 0; k < contentIndent; k++ {
			p.advance()
		}
		start := p.pos
		for !p.eof() && p.peek() != '\n' {
			p.advance()
		}
		rawLines = append(rawLines, string(p.src[start:p.pos]))
		if !p.eof() {
			p.advance()
		}
	}
	// trailing blank lines are subject to chomping
	trailing := 0
	for len(rawLines) > 0 && strings.TrimSpace(rawLines[len(rawLines)-1]) == "" && rawLines[len(rawLines)-1] == "" {
		rawLines = rawLines[:len(rawLines)-1]
		trailing++
	}
	var b strings.Builder
	if n.style == literalStyle {
		for i, l := range rawLines {
			if i > 0 {
				b.WriteByte('\n')
			}
			b.WriteString(l)
		}
	} else {
		for i, l := range rawLines {
			if i == 0 {
				b.WriteString(l)
				continue
			}
			prev := rawLines[i-1]
			moreIndented := strings.HasPrefix(l, " ") || strings.HasPrefix(l, "\t")
			prevMore := strings.HasPrefix(prev, " ") || strings.HasPrefix(prev, "\t")
			switch {
			case l == "":
				b.WriteByte('\n')
			case prev == "":
				if moreIndented || prevMore {
					b.WriteByte('\n')
				}
				b.WriteString(l)
			case moreIndented || prevMore:
				b.WriteByte('\n')
				b.WriteString(l)
			default:
				b.WriteByte(' ')
				b.WriteString(l)
			}
		}
	}
	s := b.String()
	if len(rawLines) > 0 {
		switch chomp {
		case "strip":
		case "clip":
			s += "\n"
		case "keep":
			s += "\n" + strings.Repeat("\n", trailing)
		}
	} else if chomp == "keep" {
		s = strings.Repeat("\n", trailing)
	}
	n.value = s
	return n, nil
}

// skipFlowWhitespace skips whitespace, newlines and comments in flow context.
func (p *parser) skipFlowWhitespace() {
	for !p.eof() {
		r := p.peek()
		if r == ' ' || r == '\t' || r == '\n' {
			p.advance()
			continue
		}
		if r == '#' {
			p.skipComment()
			continue
		}
		break
	}
}

// parseFlowNode parses a flow mapping or sequence starting at '{' or '['.
func (p *parser) parseFlowNode() (*node, error) {
	if p.peek() == '{' {
		return p.parseFlowMapping()
	}
	return p.parseFlowSequence()
}

func (p *parser) parseFlowMapping() (*node, error) {
	m := &node{kind: mappingNode, line: p.line, col: p.col}
	p.advance() // '{'
	seen := map[string]*node{}
	for {
		p.skipFlowWhitespace()
		if p.eof() {
			return nil, p.errorf(m.line, m.col, "could not find flow mapping end token '}'")
		}
		if p.peek() == '}' {
			p.advance()
			return m, nil
		}
		if p.peek() == ',' {
			return nil, p.errorf(p.line, p.col, "',' or '}' must be specified")
		}
		keyLine, keyCol := p.line, p.col
		key, err := p.parseFlowScalarOrNode(true)
		if err != nil {
			return nil, err
		}
		p.skipFlowWhitespace()
		if p.eof() {
			return nil, p.errorf(m.line, m.col, "could not find flow mapping end token '}'")
		}
		var val *node
		if p.peek() == ':' {
			p.advance()
			p.skipFlowWhitespace()
			if p.eof() {
				return nil, p.errorf(m.line, m.col, "could not find flow mapping end token '}'")
			}
			if p.peek() == ',' || p.peek() == '}' {
				val = &node{kind: nullNode, line: p.line, col: p.col}
			} else {
				v, err := p.parseFlowScalarOrNode(false)
				if err != nil {
					return nil, err
				}
				val = v
			}
		} else if p.peek() == ',' || p.peek() == '}' {
			val = &node{kind: nullNode, line: p.line, col: p.col}
		} else {
			return nil, p.errorf(keyLine, keyCol, "could not find flow map content")
		}
		keyStr := scalarToString(key)
		if prev, dup := seen[keyStr]; dup {
			return nil, p.errorf(keyLine, keyCol, "mapping key %q already defined at [%d:%d]", keyStr, prev.line, prev.col)
		}
		seen[keyStr] = key
		m.keys = append(m.keys, key)
		m.vals = append(m.vals, val)
		p.skipFlowWhitespace()
		if p.eof() {
			return nil, p.errorf(m.line, m.col, "could not find flow mapping end token '}'")
		}
		switch p.peek() {
		case ',':
			p.advance()
		case '}':
			p.advance()
			return m, nil
		default:
			return nil, p.errorf(p.line, p.col, "',' or '}' must be specified")
		}
	}
}

func (p *parser) parseFlowSequence() (*node, error) {
	s := &node{kind: sequenceNode, line: p.line, col: p.col}
	p.advance() // '['
	for {
		p.skipFlowWhitespace()
		if p.eof() {
			return nil, p.errorf(s.line, s.col, "sequence end token ']' not found")
		}
		if p.peek() == ']' {
			p.advance()
			return s, nil
		}
		if p.peek() == ',' {
			return nil, p.errorf(p.line, p.col, "',' or ']' must be specified")
		}
		item, err := p.parseFlowScalarOrNode(false)
		if err != nil {
			return nil, err
		}
		p.skipFlowWhitespace()
		if !p.eof() && p.peek() == ':' {
			// single pair mapping inside a sequence
			p.advance()
			p.skipFlowWhitespace()
			var val *node
			if p.eof() || p.peek() == ',' || p.peek() == ']' {
				val = &node{kind: nullNode, line: p.line, col: p.col}
			} else {
				v, err := p.parseFlowScalarOrNode(false)
				if err != nil {
					return nil, err
				}
				val = v
			}
			item = &node{kind: mappingNode, line: item.line, col: item.col, keys: []*node{item}, vals: []*node{val}}
			p.skipFlowWhitespace()
		}
		s.items = append(s.items, item)
		if p.eof() {
			return nil, p.errorf(s.line, s.col, "sequence end token ']' not found")
		}
		switch p.peek() {
		case ',':
			p.advance()
		case ']':
			p.advance()
			return s, nil
		default:
			return nil, p.errorf(p.line, p.col, "',' or ']' must be specified")
		}
	}
}

// parseFlowScalarOrNode parses a node inside a flow collection.
func (p *parser) parseFlowScalarOrNode(isKey bool) (*node, error) {
	r := p.peek()
	tag := ""
	for r == '!' || r == '&' {
		start := p.pos
		for !p.eof() && !isWhite(p.peek()) && !isFlowIndicator(p.peek()) {
			p.advance()
		}
		prop := string(p.src[start:p.pos])
		if strings.HasPrefix(prop, "!") {
			tag = prop
		}
		p.skipFlowWhitespace()
		r = p.peek()
	}
	var n *node
	var err error
	switch {
	case r == '{' || r == '[':
		n, err = p.parseFlowNode()
	case r == '"' || r == '\'':
		n, err = p.parseQuotedScalar()
	default:
		n, err = p.parseFlowPlainScalar()
	}
	if err != nil {
		return nil, err
	}
	n.tag = tag
	return n, nil
}

// parseFlowPlainScalar parses a plain scalar in flow context.
func (p *parser) parseFlowPlainScalar() (*node, error) {
	n := &node{kind: scalarNode, line: p.line, col: p.col, style: plainStyle}
	var b strings.Builder
	start := p.pos
	end := p.pos
	for !p.eof() {
		r := p.peek()
		if isFlowIndicator(r) {
			break
		}
		if r == ':' && (isWhite(p.peekAt(1)) || isFlowIndicator(p.peekAt(1))) {
			break
		}
		if r == '#' && p.pos > start && (p.src[p.pos-1] == ' ' || p.src[p.pos-1] == '\t') {
			break
		}
		if r == '\n' {
			// multi-line plain scalar in flow context: fold
			text := strings.TrimRight(string(p.src[start:end]), " \t")
			b.WriteString(text)
			p.advance()
			p.skipFlowWhitespace()
			b.WriteByte(' ')
			start = p.pos
			end = p.pos
			continue
		}
		p.advance()
		if r != ' ' && r != '\t' {
			end = p.pos
		}
	}
	b.WriteString(string(p.src[start:end]))
	n.value = strings.TrimRight(b.String(), " ")
	if n.value == "" && b.Len() == 0 {
		return nil, p.errorf(n.line, n.col, "unexpected token")
	}
	return n, nil
}

// ---------------------------------------------------------------------------
// conversion

func isNullValue(s string) bool {
	switch s {
	case "", "null", "Null", "NULL", "~":
		return true
	}
	return false
}

func isBoolValue(s string) (bool, bool) {
	switch s {
	case "true", "True", "TRUE":
		return true, true
	case "false", "False", "FALSE":
		return false, true
	}
	return false, false
}

func formatFloat(f float64) string {
	if math.IsInf(f, 1) {
		return "+Inf"
	}
	if math.IsInf(f, -1) {
		return "-Inf"
	}
	if math.IsNaN(f) {
		return "NaN"
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

// plainToString converts a plain scalar's text to its string representation
// as the decoder would when targeting a string.
func plainToString(s string) string {
	if isNullValue(s) {
		return ""
	}
	if v, ok := isBoolValue(s); ok {
		if v {
			return "true"
		}
		return "false"
	}
	switch s {
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF":
		return "+Inf"
	case "-.inf", "-.Inf", "-.INF":
		return "-Inf"
	case ".nan", ".NaN", ".NAN":
		return "NaN"
	}
	kind := numberStat(s)
	if kind == notNumber {
		return s
	}
	clean := strings.ReplaceAll(s, "_", "")
	switch kind {
	case floatNumber:
		f, err := strconv.ParseFloat(clean, 64)
		if err != nil {
			return s
		}
		return formatFloat(f)
	case intNumber, hexNumber, octalNumber, binaryNumber:
		neg := false
		body := clean
		if strings.HasPrefix(body, "-") {
			neg = true
			body = body[1:]
		} else if strings.HasPrefix(body, "+") {
			body = body[1:]
			if strings.HasPrefix(body, "-") {
				neg = true
				body = body[1:]
			}
		}
		base := 10
		switch {
		case strings.HasPrefix(body, "0x"):
			base = 16
			body = body[2:]
		case strings.HasPrefix(body, "0o"):
			base = 8
			body = body[2:]
		case strings.HasPrefix(body, "0b"):
			base = 2
			body = body[2:]
		case len(body) > 1 && body[0] == '0':
			base = 8
		}
		u, err := strconv.ParseUint(body, base, 64)
		if err != nil {
			return s
		}
		if neg {
			if u > uint64(math.MaxInt64)+1 {
				return s
			}
			return strconv.FormatInt(-int64(u), 10)
		}
		return strconv.FormatUint(u, 10)
	}
	return s
}

func scalarToString(n *node) string {
	switch n.kind {
	case nullNode:
		return ""
	case scalarNode:
		if n.tag != "" {
			switch n.tag {
			case "!!str", "!str":
				return n.value
			case "!!int", "!!float", "!!bool", "!!null":
				return plainToString(n.value)
			}
		}
		if n.style == plainStyle {
			return plainToString(n.value)
		}
		return n.value
	}
	return ""
}

func plainTypeName(n *node) string {
	if n.kind != scalarNode {
		return "string"
	}
	if n.style != plainStyle || n.tag == "!!str" {
		return "string"
	}
	s := n.value
	if isNullValue(s) {
		return "null"
	}
	if _, ok := isBoolValue(s); ok {
		return "bool"
	}
	switch numberStat(s) {
	case floatNumber:
		return "float"
	case intNumber, hexNumber, octalNumber, binaryNumber:
		clean := strings.ReplaceAll(s, "_", "")
		if _, err := strconv.ParseInt(clean, 0, 64); err == nil {
			return "int"
		}
		if _, err := strconv.ParseUint(clean, 0, 64); err == nil {
			return "uint64"
		}
		return "string"
	}
	switch s {
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF", "-.inf", "-.Inf", "-.INF", ".nan", ".NaN", ".NAN":
		return "float"
	}
	return "string"
}

// DecodeStringMap decodes the first YAML (or JSON) document in data into a
// flat map of strings, mimicking the behaviour of decoding into a
// map[string]string.
func DecodeStringMap(data []byte) (map[string]string, error) {
	if !utf8.Valid(data) {
		data = []byte(strings.ToValidUTF8(string(data), "\uFFFD"))
	}
	p := newParser(string(data))
	root, err := p.parseDocument()
	if err != nil {
		return nil, err
	}
	switch root.kind {
	case nullNode:
		return nil, errEOF
	case scalarNode:
		if plainTypeName(root) == "null" {
			return nil, errEOF
		}
		return nil, p.errorf(root.line, root.col, "%s was used where mapping is expected", plainTypeName(root))
	case sequenceNode:
		return nil, p.errorf(root.line, root.col, "sequence was used where mapping is expected")
	}
	result := make(map[string]string, len(root.keys))
	for i, k := range root.keys {
		v := root.vals[i]
		switch v.kind {
		case mappingNode:
			return nil, p.errorf(v.line, v.col, "cannot unmarshal map[string]interface {} into Go value of type string")
		case sequenceNode:
			return nil, p.errorf(v.line, v.col, "cannot unmarshal []interface {} into Go value of type string")
		}
		result[scalarToString(k)] = scalarToString(v)
	}
	return result, nil
}
