{"command":"cd /workspace; cat > cmd/jsonenc.go <<'EOF'
package cmd

import (
	"strings"
	"unicode/utf8"
)

const hexDigits = "0123456789abcdef"

// jsonQuote encodes s as a JSON string the way encoding/json does (including
// HTML-safe escaping of <, > and &).
func jsonQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); {
		c := s[i]
		if c < utf8.RuneSelf {
			if c >= 0x20 && c != '"' && c != '\\' && c != '<' && c != '>' && c != '&' {
				b.WriteByte(c)
				i++
				continue
			}
			switch c {
			case '\\', '"':
				b.WriteByte('\\')
				b.WriteByte(c)
			case '\b':
				b.WriteString(`\b`)
			case '\f':
				b.WriteString(`\f`)
			case '\n':
				b.WriteString(`\n`)
			case '\r':
				b.WriteString(`\r`)
			case '\t':
				b.WriteString(`\t`)
			default:
				b.WriteString(`\u00`)
				b.WriteByte(hexDigits[c>>4])
				b.WriteByte(hexDigits[c&0xF])
			}
			i++
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			b.WriteString(`\ufffd`)
			i += size
			continue
		}
		if r == '\u2028' || r == '\u2029' {
			b.WriteString(`\u202`)
			b.WriteByte(hexDigits[r&0xF])
			i += size
			continue
		}
		b.WriteString(s[i : i+size])
		i += size
	}
	b.WriteByte('"')
	return b.String()
}

// encodeJSONStringMap encodes the map as compact JSON with sorted keys,
// terminated by a newline.
func encodeJSONStringMap(params map[string]string) string {
	var b strings.Builder
	b.WriteByte('{')
	for i, k := range sortedKeys(params) {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonQuote(k))
		b.WriteByte(':')
		b.WriteString(jsonQuote(params[k]))
	}
	b.WriteString("}\n")
	return b.String()
}
